; 5 zero bytes nothing reads.
CmdTab_Unused label byte
	db 0h,0h,0h,0h,0h	;@84DB
; HitTile: the tile flashed where a blow lands: 3Dh (shape 61, fire) for weapons and
; the foes, 3Ch (shape 60, magic) for spells (CCmdCast, LOOP 1D5B) and the foes' magic.
HitTile label byte
	db 0h	;@84E0
; CombatPlayer, also the library's CombatPlayer: the player whose combat turn it is, 0-3. The
; library blinks that player's tile while it waits for a key in a fight.
CombatPlayer label byte	;@84E1
	db 0h	;@84E1
; FoeTile: the shape number of this fight's foes (all foes of a fight are alike): from
; the creature's tile / 4, or 18h-1Eh for a dungeon's wandering monster; a Pirate (0Fh) becomes
; a Thief (17h). 13h (Lord British) takes no damage.
FoeTile label byte
	db 0h	; FoeTile	;@84E2
; KillSpellUsed: cleared when a fight starts; the spells at MAGIC 5F9F (against Orcs,
; 18h) and 6153 (against Skeletons, 19h) set it, so they are tried once a fight.
KillSpellUsed label byte
	db 0h	; KillSpellUsed	;@84E3
; The pictures of the dungeon events (DUNEVENT), 79h bytes each, loaded over StartUp.
FileBrandImg label byte
	db 42h,52h,41h,4Eh,44h,2Eh,49h,4Dh,47h,0h	; "BRAND.IMG": the red hot rod	;@84E4
FileTimeImg label byte
	db 54h,49h,4Dh,45h,2Eh,49h,4Dh,47h,0h	; "TIME.IMG": the Time Lord	;@84EE
FileFountainImg label byte
	db 46h,4Fh,55h,4Eh,54h,41h,49h,4Eh,2Eh,49h,4Dh,47h,0h	; "FOUNTAIN.IMG"	;@84F7
; The nine combat maps (0B0h bytes, loaded over StartUp by StartCombat). FileConflict (8538) is
; CNFLCT_G (grass, and the default); the code picks one of these pointers, it patches nothing.
FileConflictA label byte
	db 43h,4Eh,46h,4Ch,43h,54h,5Fh,41h,2Eh,55h,4Ch,54h,0h	; "CNFLCT_A.ULT": pirates, party ashore	;@8504
