; PlayerTurn (COMBAT). Unused keys go to CCmdBad ("Not usable cmd!", the turn is not spent).
CombatKeys label byte
	db 55h,16h,20h,39h,0h,48h,0h,50h,0h,4Dh,0h,4Bh,56h,2Fh,0h,1Fh	; U Space Up Down Right Left V Alt-S	;@8579
	db 0h,2Fh,52h,13h,5Ah,2Ch,4Eh,31h,43h,2Eh,41h,1Eh,42h,30h,44h,20h	; Alt-V R Z N C A B D	;@8589
