	dw CCmdVolume	; Alt-V	;@85CB
	dw CCmdReady	; R: CCmdReady	;@85CD
	dw CCmdZtats	; Z: CCmdZtats	;@85CF
	dw CCmdNegate	; N: CCmdNegate	;@85D1
	dw CCmdCast	; C: CCmdCast	;@85D3
	dw CCmdAttack	; A: CCmdAttack	;@85D5
	dw CCmdBad	; the other 19 keys: CCmdBad	;@85D7
	dw CCmdBad	;@85D9
	dw CCmdBad	;@85DB
	dw CCmdBad	;@85DD
	dw CCmdBad	;@85DF
	dw CCmdBad	;@85E1
	dw CCmdBad	;@85E3
	dw CCmdBad	;@85E5
	dw CCmdBad	;@85E7
	dw CCmdBad	;@85E9
	dw CCmdBad	;@85EB
	dw CCmdBad	;@85ED
	dw CCmdBad	;@85EF
	dw CCmdBad	;@85F1
	dw CCmdBad	;@85F3
	dw CCmdBad	;@85F5
	dw CCmdBad	;@85F7
	dw CCmdBad	;@85F9
	dw CCmdBad	;@85FB
; FountainCmds: the fountain's effect by its x & 3 (DUNEVENT).
FountainCmds	dw FountainPoison	; 0: FountainPoison	;@85FD
	dw FountainHeal	; 1: FountainHeal	;@85FF
	dw FountainHurt	; 2: FountainHurt	;@8601
	dw FountainCure	; 3: FountainCure	;@8603
; FoeHitPoints, by FoeTile & 0Fh: 0 Merchant, 1 Jester, 2 Guard, 3 Lord British, 4
; Fighter, 5 Cleric, 6 Wizard, 7 Thief, 8 Orc, 9 Skeleton, A Giant, B Daemon, C Pincher, D
; Dragon (and Serpent 0Dh), E Balron (and Man-O-War 0Eh), F (Pirate, 0Fh, is fought as a Thief).
; A foe gets Random(value) | 0Fh hit points; value / 8 is added to the range of its blows.
FoeHitPoints label byte
	db 20h,20h,0F0h,0F0h,0C0h,60h,0A0h,80h,30h,50h,70h,0A0h,0C0h,0E0h,0F0h,0F0h	;@8605
